public static container getFileDataFromBase64(str _base64)
{
    int pos;
    BinData bindata;
    str base64, base64ext;
    container data;

    base64 = _base64;
    base64ext = '';

    if (base64 != '')
    {
        pos = strFind(base64, ';', 1, 60);
        if (pos)
        {
            base64ext = subStr(base64, 1, pos - 1);
        }
        pos = strFind(base64, ',', 1, 60);
        base64 = strDel(base64, 1, pos);

        bindata = new BinData();
        data = BinData::loadFromBase64(base64);
        bindata.setData(data);
    }
    return data;
}
